describe('createServer session list wiring', () => {
  it('forwards sessionStore to the message handler so list_sessions queries listFor', async () => {
    const seen: Array<string | number> = [];
    const sessionStore = {
      create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
      delete: () => true,
      listFor: async (userId: string | number) => {
        seen.push(userId);
        return [
          {
            sessionId: 's-prev',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 2,
          },
        ];
      },
    } as unknown as SessionStore;
    const noop = () => undefined;
    const hal = createServer({
      app: noop as unknown as Express,
      wsAuth: async () => null,
      sessionStore,
      orchestrator: {} as ChatOrchestrator,
    });
    const sent: Array<Record<string, unknown>> = [];
    const listeners = new Map<string, (payload: string) => void>();
    const socket = {
      userId: 'u-42',
      isAlive: true,
      send: (raw: string) => void sent.push(JSON.parse(raw) as Record<string, unknown>),
      on: (event: string, listener: (payload: string) => void) => void listeners.set(event, listener),
      pause: noop,
      resume: noop,
      close: noop,
    } as unknown as ExtWebSocket;

    hal.wss.emit('connection', socket);
    await settle();
    listeners.get('message')?.(JSON.stringify({type: 'list_sessions', userId: 'other-user'}));
    await settle();
    hal.wss.emit('close');

    expect({seen, reply: sent.at(-1)}).toEqual({
      seen: ['u-42'],
      reply: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's-prev',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 2,
          },
        ],
      },
    });
  });
});

